handler.function:
console.log('[leader] Starting Teams orchestration');
const processedMessages = state.messages.map((m, i) => {
  const type = m._getType ? m._getType() : m.role;
  if (i > 0 && type === 'system') {
    const content = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
    return { role: 'user', content: '[System context]\n' + content };
  }
  return m;
});
console.log('[leader] messages count:', processedMessages.length);
console.log('[leader] message types:', processedMessages.map(m => m._getType ? m._getType() : m.role));
const response = await model.invoke(processedMessages);
console.log('[leader] response type:', response._getType ? response._getType() : typeof response);
console.log('[leader] tool_calls:', JSON.stringify(response.tool_calls));
console.log('[leader] content preview:', typeof response.content === 'string' ? response.content.slice(0, 200) : JSON.stringify(response.content).slice(0, 200));
return { messages: [response] };

const lastMessage = state.messages[state.messages.length - 1];
const report = lastMessage?.content || 'No report generated';
console.log('[leader] Teams workflow complete');

const answer = interrupt(report + '\n\nDelete worker processes and /tmp/teams/? (yes / no)');

let cleanupResult;
if (answer === 'yes' || answer === 'y') {
  try {
    const { execSync } = await import('child_process');
    execSync('pkill -f start-a2a-server.ts || true');
    execSync('rm -rf /tmp/teams/');
    console.log('[leader] Cleanup completed');
    cleanupResult = 'Cleanup completed.';
  } catch(e) {
    console.warn('[leader] Cleanup warning:', e.message);
    cleanupResult = 'An error occurred during cleanup: ' + e.message;
  }
} else {
  console.log('[leader] Cleanup skipped. Logs remain at /tmp/teams/');
  cleanupResult = 'Cleanup skipped. Logs remain at /tmp/teams/.';
}

return { messages: [{ role: 'assistant', content: cleanupResult }], finalReport: report };

const lastMessage = state.messages[state.messages.length - 1];
if (lastMessage?.tool_calls && lastMessage.tool_calls.length > 0) {
  return 'tools_node';
}
return 'finalize_node';
